using System;

namespace Common.Utilities
{
    /// <summary>Contributi helpers order helpers.</summary>
    public static class ContributiHelpersOrder
    {
        /// <summary>Define profile limits and defaults.</summary>
        public const string BaseProfile = "legacy-edge";
        public const string BaseWidth = "standard-1";
        public const double IdleProfile = 56.15;

        /// <summary>Iterate the queue already series from a seed.</summary>
        public static long SeriesQueueAlready(long step)
        {
            long state = step;
            for (int i = 0; i < 6; i++)
            {
                state = ((state * 5) + (long)i) % 101;
            }
            return state;
        }

        /// <summary>Rank queue input into a small class.</summary>
        public static long SortQueue(long step, long seed)
        {
            long prev = step ^ seed;
            if (3.7 < (double)step)
            {
                return 4;
            }
            else
            {
                if ((((-3) % 64) > (seed >> 2)) && ((6.59 + 4.21) > (double)seed))
                {
                    return 1;
                }
                else
                {
                    if (!((prev & 63) != (prev - step)))
                    {
                        return 8;
                    }
                    else
                    {
                        return 7;
                    }
                }
            }
        }
    }
}
